css:
/* =====================================
   MAIN PAGE
===================================== */

.item-storage-page {
    width: 100%;
    padding: 15px 0 25px;
    box-sizing: border-box;
    color: var(--text-color, #36414c);
    font-family: inherit;
}


/* =====================================
   HEADER
===================================== */

.storage-header-row {
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    margin-bottom: 18px;
}

.storage-title {
    flex: 0 0 auto;
    margin: 0;
    font-size: 22px;
    font-weight: 600;
    line-height: 1.4;
    white-space: nowrap;
}

.storage-search-wrapper {
    position: relative;
    display: flex;
    align-items: center;
    flex: 1 1 auto;
    min-width: 100px;
    height: 36px;
}

.storage-search-icon {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-muted, #8d99a6);
    pointer-events: none;
}

.storage-search-input {
    width: 100%;
    height: 36px;
    padding: 8px 12px 8px 36px;
    box-sizing: border-box;
    border: 1px solid var(--border-color, #d8e0e8);
    border-radius: 8px;
    background: var(--control-bg, #f3f4f6);
    color: var(--text-color, #36414c);
    font-family: inherit;
    font-size: 13px;
    outline: none;
}

.storage-search-input:focus {
    border-color: var(--primary, #2490ef);
}

.storage-search-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    flex: 0 0 auto;
    height: 36px;
    padding: 0 17px;
    border: 1px solid #171717;
    border-radius: 8px;
    background: #171717;
    color: #ffffff;
    font-family: inherit;
    font-size: 13px;
    cursor: pointer;
    white-space: nowrap;
}

.storage-search-button:hover {
    background: #333333;
    color: #ffffff;
}


/* =====================================
   FILTER BAR
===================================== */

.storage-filter-bar {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    width: 100%;
    padding: 12px;
    margin-bottom: 18px;
    box-sizing: border-box;
    border: 1px solid var(--border-color, #d8e0e8);
    border-radius: 8px;
    background: var(--card-bg, #ffffff);
}

.storage-filter-input {
    display: block;
    width: 100%;
    min-width: 0;
    height: 35px;
    margin: 0;
    padding: 7px 10px;
    box-sizing: border-box;
    border: 1px solid transparent;
    border-radius: 7px;
    background: var(--control-bg, #f3f4f6);
    color: var(--text-color, #36414c);
    font-family: inherit;
    font-size: 12px;
    outline: none;
}

.storage-filter-input::placeholder {
    color: var(--text-muted, #8d99a6);
    opacity: 1;
}

.storage-filter-input:focus {
    border-color: var(--primary, #2490ef);
    background: var(--card-bg, #ffffff);
}

.storage-filter-clear {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    width: fit-content;
    min-width: 80px;
    height: 35px;
    padding: 0 12px;
    border: 1px solid var(--border-color, #d8e0e8);
    border-radius: 7px;
    background: var(--control-bg, #f3f4f6);
    color: var(--text-color, #36414c);
    font-family: inherit;
    font-size: 12px;
    cursor: pointer;
}

.storage-filter-clear:hover {
    background: var(--subtle-fg, #e9eef5);
}


/* =====================================
   STORAGE PANEL
===================================== */

.storage-list-container {
    width: 100%;
    overflow: hidden;
    box-sizing: border-box;
    border: 1px solid var(--border-color, #d8e0e8);
    border-radius: 9px;
    background: var(--card-bg, #ffffff);
}

.storage-list-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 10px;
    padding: 14px 16px;
    border-bottom: 1px solid var(--border-color, #d8e0e8);
}

.storage-list-heading h4 {
    margin: 0;
    font-size: 16px;
    font-weight: 600;
}

.storage-status {
    color: var(--text-muted, #8d99a6);
    font-size: 12px;
}


/* =====================================
   STORAGE TABLE
===================================== */

.storage-table-wrapper {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.storage-table {
    width: 100%;
    min-width: 1050px;
    margin: 0;
    border-collapse: collapse;
    border-spacing: 0;
    background: #ffffff;
    color: #36414c;
    font-family: inherit;
    font-size: 13px;
}

.storage-table thead th {
    padding: 13px 10px;
    border: 1px solid #cbd5e1;
    background: #e8eef6;
    color: #243447;
    font-size: 13px;
    font-weight: 700;
    text-align: left;
    vertical-align: middle;
    white-space: nowrap;
}

.storage-table tbody tr {
    background: #ffffff;
    transition: background-color 0.15s ease;
}

.storage-table tbody tr:nth-child(even) {
    background: #f5f7fa;
}

.storage-table tbody td {
    padding: 13px 10px;
    border: 1px solid #d8e0e8;
    color: #36414c;
    font-size: 13px;
    line-height: 1.5;
    text-align: left;
    vertical-align: middle;
    overflow-wrap: anywhere;
}

.storage-table tbody td:first-child {
    color: #1d4ed8;
    font-weight: 600;
    white-space: nowrap;
}

.storage-table tbody tr:hover,
.storage-table tbody tr:nth-child(even):hover {
    background: #dbeafe;
}

.storage-table .storage-empty {
    padding: 28px 12px;
    color: #64748b;
    text-align: center;
}


/* =====================================
   FOOTER NOTE
===================================== */

.storage-footer {
    padding: 12px 16px;
    border-top: 1px solid var(--border-color, #d8e0e8);
    color: var(--text-muted, #8d99a6);
    font-size: 12px;
    line-height: 1.6;
}


/* =====================================
   HIDE WEBSITE FOOTER ON THIS PAGE
===================================== */

body:has(#item-search) footer,
body:has(#item-search) .web-footer {
    display: none !important;
}


/* =====================================
   RESPONSIVE LAYOUT
===================================== */

@media (max-width: 1100px) {
    .storage-header-row {
        flex-wrap: wrap;
    }

    .storage-title {
        flex: 1 1 100%;
        white-space: normal;
    }

    .storage-search-wrapper {
        flex: 1 1 200px;
    }

    .storage-filter-bar {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 600px) {
    .storage-title {
        font-size: 19px;
    }

    .storage-search-wrapper {
        flex: 1 1 100%;
    }

    .storage-filter-bar {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
        padding: 10px;
    }

    .storage-list-heading {
        align-items: flex-start;
        flex-direction: column;
    }
}

